args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?death ?death_raw WHERE {
  VALUES ?film { <http://dbpedia.org/resource/A_Doctor%27s_Diary> dbr:Wild_Rovers }
  ?film dbo:director ?director .
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = 'en') }
  OPTIONAL { ?director dbo:deathDate ?death . }
  OPTIONAL { ?director dbp:death_date ?death_raw . }
}

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film { <http://dbpedia.org/resource/A_Doctor%27s_Diary> dbr:Wild_Rovers }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = 'en') }
  {
    ?film dbo:director ?director .
  }
  UNION
  {
    ?film dbp:director ?director .
  }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = 'en') }
  OPTIONAL { ?director dbo:deathDate ?deathDate . }
  OPTIONAL { ?director dbp:death_date ?deathDate . }
} ORDER BY ?film

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film { <http://dbpedia.org/resource/A_Doctor's_Diary> dbr:Wild_Rovers }
  ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = 'en') .
  { ?film dbo:director ?director } UNION { ?film dbp:director ?director } .
  ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = 'en') .
  OPTIONAL { ?director dbo:deathDate ?d1 . }
  OPTIONAL { ?director dbp:death_date ?d2 . }
  BIND(COALESCE(?d1, ?d2) AS ?deathRaw)
  BIND(xsd:date(str(?deathRaw)) AS ?deathDate)
} ORDER BY ?deathDate LIMIT 1

