PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film {
    <http://dbpedia.org/resource/A_Doctor's_Diary> dbr:Wild_Rovers
  }
  ?film rdfs:label ?filmLabel
  FILTER(lang(?filmLabel) = 'en')
  .
  {
    ?film dbo:director ?director
  } UNION {
    ?film dbp:director ?director
  }
  .
  ?director rdfs:label ?directorLabel
  FILTER(lang(?directorLabel) = 'en')
  .
  OPTIONAL {
    ?director dbo:deathDate ?d1 .
  }
  OPTIONAL {
    ?director dbp:death_date ?d2 .
  }
  BIND(COALESCE(?d1 , ?d2) AS ?deathRaw)
  BIND(xsd:date(str(?deathRaw)) AS ?deathDate)
}
ORDER BY ?deathDate
LIMIT 1

